  authz_int."chat__check_9376e67d6d"(p_row "ms"."chats");

-- The app role must not be the policy's owner, nor a member of it: the rules would not hold for it
DO $ar$
DECLARE v_app name;
BEGIN
  SELECT a.rolname INTO v_app FROM pg_catalog.pg_roles a
  WHERE a.rolname = 'ms_app' AND NOT a.rolsuper AND pg_catalog.pg_has_role(a.oid, CURRENT_USER, 'MEMBER');
  IF v_app IS NOT NULL THEN
    RAISE EXCEPTION 'the app role % is the role that applies the policy (%), or a member of it: the rules would not hold for it [AZ624]', v_app, CURRENT_USER
      USING HINT = 'the policy''s owner skips row-level security, may turn it off, and is believed without a signature: the app connects as a role of its own, which owns nothing of the database';
  END IF;
END $ar$;

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

CREATE OR REPLACE FUNCTION authz_int."chat__col_audit_upd"() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
    -- the rows whose key changed, or a column access may read: a relation's, or one a condition names (a
    -- column no rule reads changes no access, and isn't announced)
    PERFORM authz_int.changed('chat', ARRAY(
        SELECT n."id"::text FROM new_rows n WHERE NOT EXISTS (SELECT 1 FROM old_rows o WHERE o."id"::text = n."id"::text)
        UNION SELECT o."id"::text FROM old_rows o WHERE NOT EXISTS (SELECT 1 FROM new_rows n WHERE n."id"::text = o."id"::text)
        UNION SELECT n."id"::text FROM new_rows n JOIN old_rows o ON n."id"::text = o."id"::text
        WHERE n."created_by" IS DISTINCT FROM o."created_by" OR (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(n)) e WHERE lower(e.key) = ANY (ARRAY['admins_only', 'chat_id', 'direct_pairs', 'exists', 'from', 'kind', 'm', 'members', 'ms', 'not', 'p', 'select', 'this', 'where'])) IS DISTINCT FROM (SELECT jsonb_object_agg(e.key, e.value) FROM jsonb_each(to_jsonb(o)) e WHERE lower(e.key) = ANY (ARRAY['admins_only', 'chat_id', 'direct_pairs', 'exists', 'from', 'kind', 'm', 'members', 'ms', 'not', 'p', 'select', 'this', 'where']))), 'update');
    -- a partitioned table: the rows this update put in another partition, which the row trigger never sees
    IF (SELECT relkind FROM pg_class WHERE oid = TG_RELID) = 'p' THEN
      INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation, subject_id, detail, reason)
      SELECT authz_int.caller_role(), authz_int.actor(), nullif(current_setting('authz.acting_user', true), ''), 'relate', 'chat', n."id"::text, 'creator', n."created_by"::text, jsonb_build_object('column', 'created_by', 'was', o."created_by"), nullif(current_setting('authz_ctx.reason', true), '')
      FROM old_rows o JOIN new_rows n ON n."id"::text = o."id"::text
      WHERE n."created_by" IS DISTINCT FROM o."created_by" AND NOT EXISTS (
        SELECT 1 FROM authz.audit a WHERE a.txid = txid_current() AND a.action = 'relate' AND a.object_type = 'chat'
          AND a.object_id = n."id"::text AND a.relation = 'creator' AND a.detail->>'column' = 'created_by'
          AND a.subject_id IS NOT DISTINCT FROM n."created_by"::text AND a.detail->'was' IS NOT DISTINCT FROM to_jsonb(o."created_by"));
    END IF;
  RETURN NULL;
END $f$;

-- chat.setup (line 35): creator and {not exists (select 1 from ms.members m where m.chat_id = this.id)} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)}
CREATE OR REPLACE VIEW authz_int."chat__setup" AS
  SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = r.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false);

-- chat.add_members (line 38): manage or (creator and member and {kind = 'direct'} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)})
CREATE OR REPLACE VIEW authz_int."chat__add_members" AS
  (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__admin")
    AND coalesce((kind = 'group'), false))
  UNION ALL
  (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND r."id" IN (SELECT id FROM authz_int."chat__member")
    AND coalesce((kind = 'direct'), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false));

-- chat: a condition that reads other rows, run with the policy's rights wherever it is checked
CREATE FUNCTION authz_int."chat__check_3b30cbf010"(p_row "ms"."chats") RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
  SELECT coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = "chats".id)), false) FROM (SELECT (p_row).*) AS "chats"
$f$;

-- ms.chats: no row has the id, or the user may select it (what the rules' explanations answer for)
CREATE OR REPLACE FUNCTION authz_int."ms.chats:seen"(p_id bigint) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  RETURN NOT EXISTS (SELECT 1 FROM "ms"."chats" o WHERE o."id" = p_id)
      OR EXISTS (SELECT 1 FROM "ms"."chats" "chats" WHERE "chats"."id" = p_id
        AND (SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = "chats".id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = "chats".id)), false))));
END $f$;

-- ms.chats select (line 79): read or join or setup
CREATE POLICY "authz_select" ON "ms"."chats" FOR SELECT TO "ms_app"
  USING (((SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND authz_int."chat__check_ecbdd5ff4d"(("chats".*)::"ms"."chats")
    AND authz_int."chat__check_3b30cbf010"(("chats".*)::"ms"."chats")))));
COMMENT ON POLICY "authz_select" ON "ms"."chats" IS 'rowstile';

CREATE FUNCTION authz_gen."ms.members:insert:items"(p_row "ms"."members") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT CASE WHEN authz_int."ms.members:seen"(ROW("members"."chat_id"::bigint, "members"."user_id"::uuid)::text) THEN ARRAY[
    coalesce(((EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."user__has_blocked" v WHERE v.id = "members"."user_id"), false))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__setup" v WHERE v.id = "members"."chat_id"))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__join" v WHERE v.id = "members"."chat_id"))), false),
    coalesce((SELECT authz_int.scope_cmd('ms.members', 'insert')), false),
    coalesce(true, false),
    coalesce((EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."user__has_blocked" v WHERE v.id = "members"."user_id"), false)), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id"), false),
    coalesce((coalesce((role = 'member'), false)
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id"))), false),
    coalesce(NOT coalesce(EXISTS (SELECT 1 FROM authz_int."user__has_blocked" v WHERE v.id = "members"."user_id"), false), false),
    coalesce((coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__setup" v WHERE v.id = "members"."chat_id")), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."chat__setup" v WHERE v.id = "members"."chat_id"), false),
    coalesce(coalesce("members"."user_id" = (SELECT authz.uid()), false), false),
    coalesce((coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__join" v WHERE v.id = "members"."chat_id")), false),
    coalesce(EXISTS (SELECT 1 FROM authz_int."chat__join" v WHERE v.id = "members"."chat_id"), false),
    coalesce(coalesce("members"."user_id" = (SELECT authz.uid()), false), false),
    coalesce(coalesce((role = 'member'), false), false)]
    ELSE pg_catalog.array_fill(false, ARRAY[14]) END
  FROM pg_catalog.unnest(ARRAY[p_row]) AS "members";
END;

CREATE OR REPLACE FUNCTION authz_gen."ms.members:insert:why"(p_row "ms"."members") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."ms.members:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : (chat.add_members and ({role = ''member''} or (chat.manage and {role <> ''owner''})) and not person.has_blocked) or (chat.setup and person) or (chat.join and person and {role = ''member''})  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule ms.members insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on ms.members'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || '(chat.add_members and ({role = ''member''} or (chat.manage and {role <> ''owner''})) and not person.has_blocked)';
  IF NOT v[4] THEN
    RETURN NEXT CASE WHEN v[5] THEN '    yes  ' ELSE '    no   ' END || 'chat.add_members';
  IF NOT v[5] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'add_members') l LIMIT 20;
    END LOOP;
  END IF;
    RETURN NEXT CASE WHEN v[6] THEN '    yes  ' ELSE '    no   ' END || '({role = ''member''} or (chat.manage and {role <> ''owner''}))';
    RETURN NEXT CASE WHEN v[7] THEN '    yes  ' ELSE '    no   ' END || 'not person.has_blocked';
  END IF;
  RETURN NEXT CASE WHEN v[8] THEN '  yes  ' ELSE '  no   ' END || '(chat.setup and person)';
  IF NOT v[8] THEN
    RETURN NEXT CASE WHEN v[9] THEN '    yes  ' ELSE '    no   ' END || 'chat.setup';
  IF NOT v[9] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'setup') l LIMIT 20;
    END LOOP;
  END IF;
    RETURN NEXT CASE WHEN v[10] THEN '    yes  ' ELSE '    no   ' END || 'person';
  END IF;
  RETURN NEXT CASE WHEN v[11] THEN '  yes  ' ELSE '  no   ' END || '(chat.join and person and {role = ''member''})';
  IF NOT v[11] THEN
    RETURN NEXT CASE WHEN v[12] THEN '    yes  ' ELSE '    no   ' END || 'chat.join';
  IF NOT v[12] THEN
    FOR v_t IN SELECT DISTINCT x.id FROM (SELECT ("members"."chat_id")::text AS id FROM (SELECT (p_row).*) AS "members") x WHERE x.id IS NOT NULL ORDER BY 1 LIMIT 3 LOOP
      RETURN QUERY SELECT '      ' || l FROM authz.explain('chat', v_t.id, 'join') l LIMIT 20;
    END LOOP;
  END IF;
    RETURN NEXT CASE WHEN v[13] THEN '    yes  ' ELSE '    no   ' END || 'person';
    RETURN NEXT CASE WHEN v[14] THEN '    yes  ' ELSE '    no   ' END || '{role = ''member''}';
  END IF;
END $f$;

-- ms.members insert (line 90): (chat.add_members and ({role = 'member'} or (chat.manage and {role <> 'owner'})) and not person.has_blocked) or (chat.setup and person) or (chat.join and person and {role = 'member'})
CREATE POLICY "authz_insert" ON "ms"."members" FOR INSERT TO "ms_app"
  WITH CHECK (((SELECT authz_int.scope_cmd('ms.members', 'insert')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__add_members" v WHERE v.id = "members"."chat_id")
    AND (coalesce((role = 'member'), false)
    OR (coalesce((role <> 'owner'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = "members"."chat_id")))
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."user__has_blocked" v WHERE v.id = "members"."user_id"), false))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__setup" v WHERE v.id = "members"."chat_id"))
    OR (coalesce("members"."user_id" = (SELECT authz.uid()), false)
    AND coalesce((role = 'member'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__join" v WHERE v.id = "members"."chat_id"))))
    OR authz_gen."ms.members:insert:refuse"(("members".*)::"ms"."members"));
COMMENT ON POLICY "authz_insert" ON "ms"."members" IS 'rowstile';

-- A permission on an object, whether the user may select its row or not: what the functions that act on the
-- object ask (sharing, roles, keys, view_as, break_glass, requests), where authz.can's answer is for rows they may see
CREATE OR REPLACE FUNCTION authz_int.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_bigint bigint; v_text text; v_uuid uuid;
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'user' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'uuid') THEN RETURN false; END IF;
      v_uuid := p_id::uuid;
      CASE p_perm
        WHEN 'edit' THEN RETURN EXISTS (SELECT 1 FROM "ms"."users" o WHERE o."id" = v_uuid AND (coalesce(o."id" = (SELECT authz.uid()), false)));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    WHEN 'bot' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'manage' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))));
        WHEN 'manage_keys' THEN RETURN EXISTS (SELECT 1 FROM "ms"."bots" o WHERE o."id" = v_bigint AND ((coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false))));
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
