-- Every object the user holds a permission on, whether they may select its row or not: what the access previews
-- (rowstile diff, the review's access, rowstile snapshot) list, run as the owner. authz.list where it is the same
CREATE OR REPLACE FUNCTION authz_int.list(p_type text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'user.edit' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."users" o
        WHERE coalesce(o."id" = (SELECT authz.uid()), false);
    WHEN 'bot.manage' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
    WHEN 'bot.manage_keys' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."bots" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    AND coalesce((active), false));
    WHEN 'chat.post' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND NOT coalesce(EXISTS (SELECT 1 FROM authz_int."chat__blocked" v WHERE v.id = o."id"), false)
    AND (coalesce((not admins_only), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id")))
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = o."id"));
    WHEN 'chat.invite' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"));
    WHEN 'chat.add_members' THEN
      RETURN QUERY SELECT o."id"::text FROM "ms"."chats" o
        WHERE ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = o."id"))
    OR (coalesce(o."created_by" = (SELECT authz.uid()), false)
    AND coalesce((kind = 'direct'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = o."id")
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = o.id)), false)));
    WHEN 'message.edit' THEN
      RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    AND coalesce((not deleted and created_at > now() - interval '15 minutes'), false));
    WHEN 'message.remove' THEN
      RETURN QUERY SELECT ROW(o."chat_id"::bigint, o."seq"::bigint)::text FROM "ms"."messages" o
        WHERE (coalesce(o."sender_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_int."chat__manage" v WHERE v.id = o."chat_id"));
    ELSE
      RETURN QUERY SELECT * FROM authz.list(p_type, p_perm);
  END CASE;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."chat__add_members__who"(p_id bigint) RETURNS SETOF uuid
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."chat__manage__who"(p_id) x)
  UNION ALL
  ((SELECT x FROM authz_int."chat__creator__who"(p_id) x) INTERSECT (SELECT x FROM authz_int."chat__member__who"(p_id) x))
$f$;

CREATE OR REPLACE FUNCTION authz_int."chat__setup__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."chat__setup");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'chat.setup = creator and {not exists (select 1 from ms.members m where m.chat_id = this.id)} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)}';
  BEGIN
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = r.id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(creator and {not exists (select 1 from ms.members m where m.chat_id = this.id)} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__creator");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'creator';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."chat__creator__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((not exists (select 1 from ms.members m where m.chat_id = r.id)), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not exists (select 1 from ms.members m where m.chat_id = this.id)}';
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)}';
  END;
END $f$;

CREATE OR REPLACE FUNCTION authz_int."chat__add_members__why"(p_id bigint, p_depth int, p_seen text[], p_asker text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."chat__add_members");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'chat.add_members = manage or (creator and member and {kind = ''direct''} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)})';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__manage");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'manage';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."chat__manage__why"(p_id, p_depth + 1, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r
  WHERE r."id" IN (SELECT id FROM authz_int."chat__creator")
    AND r."id" IN (SELECT id FROM authz_int."chat__member")
    AND coalesce((kind = 'direct'), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false));
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '(creator and member and {kind = ''direct''} and {not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)})';
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__creator");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'creator';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."chat__creator__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."chat__member");
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'member';
    IF v_ok AND v_holds THEN RETURN QUERY SELECT * FROM authz_int."chat__member__why"(p_id, p_depth + 2, p_seen, p_asker); END IF;
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((kind = 'direct'), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{kind = ''direct''}';
    v_ok := (p_id) IN (SELECT r."id" AS id FROM "ms"."chats" r WHERE coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = r.id)), false));
    RETURN NEXT pad || '  ' || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || '{not exists (select 1 from ms.direct_pairs p where p.chat_id = this.id)}';
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE OR REPLACE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."users" "users" WHERE "users"."id" = p_id::uuid
        AND (SELECT authz_int.scope_cmd('ms.users', 'select')) AND coalesce(((SELECT authz.uid()) IS NOT NULL), false));
    WHEN 'bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."bots" "bots" WHERE "bots"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.bots', 'select')) AND (coalesce(((SELECT authz.uid()) IS NOT NULL), false)
    AND coalesce((active), false)));
    WHEN 'chat' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chats" "chats" WHERE "chats"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('ms.chats', 'select')) AND ((EXISTS (SELECT 1 FROM authz_int."chat__member" v WHERE v.id = "chats"."id")
    OR EXISTS (SELECT 1 FROM authz_int."chat__bot" v WHERE v.id = "chats"."id"))
    OR ((coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__invitee" v WHERE v.id = "chats"."id"))
    OR (coalesce((kind = 'group'), false)
    AND EXISTS (SELECT 1 FROM authz_int."chat__admin" v WHERE v.id = "chats"."id")))
    OR (coalesce("chats"."created_by" = (SELECT authz.uid()), false)
    AND coalesce((not exists (select 1 from ms.members m where m.chat_id = "chats".id)), false)
    AND coalesce((not exists (select 1 from ms.direct_pairs p where p.chat_id = "chats".id)), false))));
    WHEN 'membership' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."members" "members" WHERE ("members"."chat_id", "members"."user_id") = (((p_id)::authz_gen."membership__key")."chat_id", ((p_id)::authz_gen."membership__key")."user_id")
        AND (SELECT authz_int.scope_cmd('ms.members', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "members"."chat_id"));
    WHEN 'message' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."messages" "messages" WHERE ("messages"."chat_id", "messages"."seq") = (((p_id)::authz_gen."message__key")."chat_id", ((p_id)::authz_gen."message__key")."seq")
        AND (SELECT authz_int.scope_cmd('ms.messages', 'select')) AND (authz_int."message__check_522cac4d84"(("messages".*)::"ms"."messages")
    AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "messages"."chat_id")));
    WHEN 'chat_bot' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."chat_bots" "chat_bots" WHERE ("chat_bots"."chat_id", "chat_bots"."bot_id") = (((p_id)::authz_gen."chat_bot__key")."chat_id", ((p_id)::authz_gen."chat_bot__key")."bot_id")
        AND (SELECT authz_int.scope_cmd('ms.chat_bots', 'select')) AND EXISTS (SELECT 1 FROM authz_int."chat__read" v WHERE v.id = "chat_bots"."chat_id"));
    WHEN 'block' THEN
      RETURN EXISTS (SELECT 1 FROM "ms"."blocks" "blocks" WHERE ("blocks"."blocker_id", "blocks"."blocked_id") = (((p_id)::authz_gen."block__key")."blocker_id", ((p_id)::authz_gen."block__key")."blocked_id")
        AND (SELECT authz_int.scope_cmd('ms.blocks', 'select')) AND coalesce("blocks"."blocker_id" = (SELECT authz.uid()), false));
    ELSE RETURN false;
  END CASE;
END $f$;

